import re


_LINE_RE = re.compile(
    r"^JOB\s+(\S+)\s+AT\s+(\d{2}:\d{2})\s+RUN\s+(\S+)"
    r"(?:\s+ON_ERROR\s+(ABORT|CONTINUE|RETRY:\d+))?\s*$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse Meridian CRM batch_jobs.cfg text into modern schedule entries."""
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _LINE_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid batch job configuration at line {line_number}")

        name, at, script, error_clause = match.groups()
        hour, minute = map(int, at.split(":"))
        if hour > 23 or minute > 59:
            raise ValueError(f"Invalid time at line {line_number}: {at}")

        if error_clause is None or error_clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif error_clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(error_clause.split(":", 1)[1]),
            }

        schedule.append(
            {
                "name": name,
                "at": at,
                "script": script,
                "on_error": on_error,
            }
        )

    return schedule
